kout_total_minor": calibrated.total_minor, "context": CONTEXT.model_dump(mode="json"), "quantity": 1, } facts["calibration_sha256"] = digest(frozen) lane.stack.record("P3-V01-frozen-calibration", **frozen, sha256=facts["calibration_sha256"]) lane.proxy.reset() exercise(lane, c, v, raw, case_id, facts) cal_after = state(lane, c) assert cal_after["offers"] == cal_done["offers"] assert cal_after["checkouts"] == cal_done["checkouts"] for name in cal_done["tables"]: if name != "run_events" or case_id not in {"foreign-run", "foreign-actor"}: assert cal_after["tables"][name] == cal_done["tables"][name], name assert psp_state(lane) == psp_before assert not lane.proxy.errors, lane.proxy.errors assert not [call for call in lane.proxy.calls if call.fault == "blocked"] status = "passed" except BaseException as error: facts["error_type"] = type(error).__name__ raise finally: lane.proxy.faults.clear() lane.proxy.response_transform.clear() lane.proxy.before_forward.clear() lane.proxy.after_answer.clear() try: > facts["final"] = {ep.run_id: summary(cleanup(lane, ep)) for ep in episodes} ^^^^^^^^^^^^^^^^^
