@pytest.mark.parametrize("case_id", CASES) def test_offer_checkout_contract(p3_lane: PurchaseLane, case_id: str): lane = p3_lane lane.proxy.reset() facts: dict[str, Any] = {"case_id": case_id, "cleanup_verified": False, "commercial": "unknown"} episodes: list[Episode] = [] status = "failed" try: c, v = lane.episode("calibration"), lane.episode("validation") episodes.extend((c, v)) cs, vs = state(lane, c), state(lane, v) assert c.run_id != v.run_id and c.actor_id != v.actor_id assert (cs["actor_id"], vs["actor_id"]) == (c.actor_id, v.actor_id) assert cs["matches_full_fixture"] and vs["matches_full_fixture"] assert cs["offers"] == vs["offers"] and cs["clock_at"] == vs["clock_at"] assert not cs["checkouts"] and not vs["checkouts"] facts["initial"] = {"calibration": summary(cs), "validation": summary(vs)} psp_before = psp_state(lane) facts["psp_before"] = psp_before positive = case_id != "stable-zero" eligible = [ o for o in cs["offers"] if o["product_status"] == "active" and o["available_quantity"] > 0 and (o["pricing"]["shipping_total_minor"] > 0) == positive ] assert len(eligible) >= 2, "BLOCKED: insufficient full catalog attributes" raw = sorted(eligible, key=lambda o: (o["brand"], o["name"], o["id"]))[0] with client(lane, c) as gateway: observed = gateway.get_offer(raw["id"], CONTEXT) assert observed.model_dump(mode="json") == raw calibrated = prepare(lane, c, observed, facts) facts["calibration"] = { "offer": raw, "total_minor": calibrated.total_minor, "frozen_before_validation": True, } cal_done = cleanup(lane, c) # No shared run effects, and no payment preparation, even in calibration. after_calibration = state(lane, v) assert {k: val for k, val in after_calibration.items() if not k.startswith("global_")} == { k: val for k, val in vs.items() if not k.startswith("global_") } assert psp_state(lane) == psp_before facts["calibration_clean"] = summary(cal_done) frozen = { "case_id": case_id, "calibration_run": c.run_id, "validation_run": v.run_id, "offer": raw, "checkout_total_minor": calibrated.total_minor, "context": CONTEXT.model_dump(mode="json"), "quantity": 1, } facts["calibration_sha256"] = digest(frozen) lane.stack.record("P3-V01-frozen-calibration", **frozen, sha256=facts["calibration_sha256"]) lane.proxy.reset() exercise(lane, c, v, raw, case_id, facts) cal_after = state(lane, c) assert cal_after["offers"] == cal_done["offers"] assert cal_after["checkouts"] == cal_done["checkouts"] for name in cal_done["tables"]: if name != "run_events" or case_id not in {"foreign-run", "foreign-actor"}: assert cal_after["tables"][name] == cal_done["tables"][name], name assert psp_state(lane) == psp_before assert not lane.proxy.errors, lane.proxy.errors assert not [call for call in lane.proxy.calls if call.fault == "blocked"] status = "passed" except BaseException as error: facts["error_type"] = type(error).__name__ raise finally: lane.proxy.faults.clear() lane.proxy.response_transform.clear() lane.proxy.before_forward.clear() lane.proxy.after_answer.clear() try: > facts["final"] = {ep.run_id: summary(cleanup(lane, ep)) for ep in episodes} ^^^^^^^^^^^^^^^^^
